package asem.uniproject3;

import java.util.EmptyStackException;

public class CStack <T extends Comparable<T>> implements Stackable<T>
{
    private CursorArray<T> ca ;
    private  int l;

    public CStack(){
        ca = new CursorArray<>(100);
        l = ca.createList();
    }
    public CStack(int capacity){
        if(capacity > 0) {
            ca = new CursorArray<>(capacity + 2);// +2 for the dummy heads
            l = ca.createList();
        }

    }


    @Override
    public void push(T data) {
        if (!ca.isEmpty()) {
            ca.insertFirst(l, data);
        }
    }

    @Override
    public T pop() {
        if (!isEmpty())
            return ca.deleteFirst(l);
        else
            throw new EmptyStackException();
    }

    @Override
    public T peek() {
        if (!isEmpty())
            return ca.getFirst(l);
        else
            throw  new EmptyStackException();
    }

    @Override
    public boolean isEmpty() {
        return ca.isEmpty(l);
    }

    @Override
    public void clear() {
        ca.clear(l);
    }
}

package asem.uniproject3;

import java.util.EmptyStackException;

public class CStack <T extends Comparable<T>> implements Stackable<T>
{
    private CursorArray<T> ca ;
    private  int l;

    public CStack(){
        ca = new CursorArray<>(100);
        l = ca.createList();
    }
    public CStack(int capacity){
        if(capacity > 0) {
            ca = new CursorArray<>(capacity + 2);// +2 for the dummy heads
            l = ca.createList();
        }

    }


    @Override
    public void push(T data) {
        // always insert at list head
        ca.insertFirst(l, data);
    }

    @Override
    public T pop() {
        if (!isEmpty())
            return ca.deleteFirst(l);
        else
            throw new EmptyStackException();
    }

    @Override
    public T peek() {
        if (!isEmpty())
            return ca.getFirst(l);
        else
            throw  new EmptyStackException();
    }

    @Override
    public boolean isEmpty() {
        return ca.isEmpty(l);
    }

    @Override
    public void clear() {
        ca.clear(l);
    }
}

package asem.uniproject3;

public class Converter {

    public String infixToPostfix(String exp, OperatorRules rule) {
        StringBuilder res = new StringBuilder();
        CStack<Character> stack = new CStack<>();

        String isValid = validate(exp, rule, "infix");
        if (isValid == null) {
            for (int i = 0; i < exp.length(); i++) {
                char curr = exp.charAt(i);

                if (curr == ' ') {
                    continue;
                }

                if (Character.isLetterOrDigit(curr)) {
                    res.append(curr).append(' ');
                } else if (curr == '(') {
                    stack.push(curr);
                } else if (curr == ')') { // push everything until '(' and append to res
                    while (!stack.isEmpty() && stack.peek() != '(') {
                        res.append(stack.pop()).append(' ');
                    }
                    if (!stack.isEmpty()) {// to make sure to pop '('
                        stack.pop();
                    }
                } else if (rule.getPriority(curr) != -1) { // it operator
                    while (!stack.isEmpty() && stack.peek() != '(' && rule.getPriority(stack.peek()) >= rule.getPriority(curr)) {
                        res.append(stack.pop());
                    }
                    stack.push(curr);
                }
            }

            while (!stack.isEmpty()) {
                res.append(stack.pop());
            }

            return res.toString();
        }
        return null;
    }

    public String infixToPrefix(String exp, OperatorRules rule) {
        StringBuilder res = new StringBuilder();
        CStack<Character> stack = new CStack<>();
        String isValid = validate(exp, rule, "infix");

        if (isValid == null) {
            String reversed = new StringBuilder(exp).reverse().toString();

            StringBuilder swapped = new StringBuilder(); // to store correct parentheses order
            for (char c : reversed.toCharArray()) {
                if (c == '(') {
                    swapped.append(')');
                } else if (c == ')') {
                    swapped.append('(');
                } else {
                    swapped.append(c);
                }
            }
            String postfix = infixToPostfix(swapped.toString(), rule);

            return new StringBuilder(postfix).reverse().toString();
        }
        return null;
    }

    public String postfixToInfix(String exp, OperatorRules rule) {
        CStack<String> stack = new CStack<>();
        String isValid = validate(exp, rule, "postfix");

        if (isValid == null) {
            for (int i = 0; i < exp.length(); i++) {
                char curr = exp.charAt(i);

                if (curr == ' ') {
                    continue;
                }

                if (Character.isLetterOrDigit(curr)) {
                    stack.push(String.valueOf(curr));
                } else if (rule.getPriority(curr) != -1) {
                    String operand2 = stack.pop();
                    String operand1 = stack.pop();
                    String infix = "(" + operand1 + curr + operand2 + ")";
                    stack.push(infix);
                }
            }

            return stack.pop();
        }
        return null;
    }

    public String prefixToInfix(String exp, OperatorRules rule) {
        CStack<String> stack = new CStack<>();
        String isValid = validate(exp, rule, "prefix");

        if (isValid == null) {
            for (int i = exp.length() - 1; i >= 0; i--) {
                char curr = exp.charAt(i);

                if (curr == ' ') {
                    continue;
                }

                if (Character.isLetterOrDigit(curr)) {
                    stack.push(String.valueOf(curr));
                } else if (rule.getPriority(curr) != -1) {
                    String operand1 = stack.pop();
                    String operand2 = stack.pop();
                    String infix = "(" + operand1 + curr + operand2 + ")";
                    stack.push(infix);
                }
            }

            return stack.pop();
        }
        return null;
    }

    public String postfixToPrefix(String exp, OperatorRules rule) {
        String infix = postfixToInfix(exp, rule);
        return infixToPrefix(infix, rule);
    }

    public double evaluatePostfix(String exp) {

        CStack<Double> stack = new CStack<>();
        StringBuilder number = new StringBuilder();

        for (int i = 0; i < exp.length(); i++) {
            char curr = exp.charAt(i);

            if (Character.isWhitespace(curr)) {
                if (number.length() > 0) {
                    stack.push(Double.parseDouble(number.toString()));
                    number.setLength(0);
                }
                continue;
            }

            if (Character.isDigit(curr) || curr == '.') {
                number.append(curr);
                continue;
            }

            if (number.length() > 0) {
                stack.push(Double.parseDouble(number.toString()));
                number.setLength(0);
            }

            double operand2 = stack.pop();
            double operand1 = stack.pop();

            switch (curr) {
                case '+':
                    stack.push(operand1 + operand2);
                    break;
                case '-':
                    stack.push(operand1 - operand2);
                    break;
                case '*':
                    stack.push(operand1 * operand2);
                    break;
                case '/':
                    stack.push(operand1 / operand2);
                    break;
                case '^':
                    stack.push(Math.pow(operand1, operand2));
                    break;

            }
        }

        if (number.length() > 0) {
            stack.push(Double.parseDouble(number.toString()));
        }

        return stack.pop();

    }

    public double evaluatePrefix(String exp) {

        CStack<Double> stack = new CStack<>();

        for (int i = exp.length() - 1; i >= 0; i--) {
            char c = exp.charAt(i);

            if (c == ' ') {
                continue;
            }

            if (Character.isDigit(c)) {
                stack.push((double) (c - '0'));
            } else {

                double num1 = stack.pop();
                double num2 = stack.pop();

                switch (c) {
                    case '+':
                        stack.push(num1 + num2);
                        break;
                    case '-':
                        stack.push(num1 - num2);
                        break;
                    case '*':
                        stack.push(num1 * num2);
                        break;
                    case '/':
                        if (num2 == 0) {
                            throw new ArithmeticException("Division by zero!");
                        }
                        stack.push(num1 / num2);
                        break;
                    case '^':
                        stack.push(Math.pow(num1, num2));
                        break;
                    case '%':
                        stack.push(num1 % num2);
                        break;
                }
            }
        }
        return stack.pop();

    }


    // null is valid else the error msg
    public String validate(String exp, OperatorRules rule, String type) {

        if (exp == null || exp.trim().isEmpty()) {
            return "Error: Expression cannot be empty";
        }

        int parenthesesBalance = 0;
        int operandCount = 0;
        int operatorCount = 0;


        char firstChar = ' '; // not space
        char lastChar = ' '; // not space

        for (int i = 0; i < exp.length(); i++) {
            char curr = exp.charAt(i);

            if (curr == ' ') {
                continue;
            }
            if (firstChar == ' ') {
                firstChar = curr;
            }
            if (curr == '(') {
                parenthesesBalance++;
                lastChar = curr;
                continue;
            }
            if (curr == ')') {
                parenthesesBalance--;
                if (parenthesesBalance < 0) {
                    return "Error: Mismatched parentheses";
                }
                lastChar = curr;
                continue;
            }
            // curr char is operator
            if (rule.isOperator(curr)) {
                operatorCount++;

                if (type.equalsIgnoreCase("infix")) {
                    if (rule.isOperator(lastChar) || lastChar == '(') {
                        return "Error: cant be two operators beside each other in infix";
                    }
                }

                lastChar = curr;
                continue;

            }
            // curr is operand
            else if (rule.fromDomain(curr)) {
                operandCount++;
                if (type.equalsIgnoreCase("infix")) {
                    if (rule.fromDomain(lastChar) || lastChar == ')') {
                        return "Error: cant two operand beside other in infix";
                    }
                }
                lastChar = curr;
                continue;

            }
            return "Error: undefined operand";
        }
        if (parenthesesBalance != 0) {
            return "Error: Mismatched parentheses";
        }
        if (operandCount != (operatorCount + 1)) { // in binary operator
            return "Error:  Missing an operator or operand";
        }
        // first char or last is operator
        if (type.equalsIgnoreCase("infix") && (rule.isOperator(firstChar) || rule.isOperator(lastChar))) {
            return "Error: infix not start or end with operator";
        } else if (type.equalsIgnoreCase("postfix")) {
            if (rule.isOperator(firstChar)) {// first char cannot be operator
                return "Error: first char cannot be operator in postfix";
            }
            if (!rule.isOperator(lastChar)) { // last char should be an operator
                return "Error: last char should be an operator in postfix";
            }
        } else if (type.equalsIgnoreCase("PREFIX")) {
            if (rule.isOperator(firstChar)) {
                return "Error: should start with operator in prefix";
            }
            if (rule.isOperator(lastChar)) {
                return "Error: cannot end with operator in prefix";
            }
        }
        return null;

    }

}

