        StringBuilder res = new StringBuilder();
        CStack<Character> stack = new CStack<>();
        String isValid = validate(exp, rule, "infix");

        if (isValid == null) {
            // Reverse the infix, swap parentheses, convert to postfix, then reverse tokens to get prefix
            String reversed = new StringBuilder(exp).reverse().toString();
            StringBuilder swapped = new StringBuilder(); // to store correct parentheses order
            for (char c : reversed.toCharArray()) {
                if (c == '(') {
                    swapped.append(')');
                } else if (c == ')') {
                    swapped.append('(');
                } else {
                    swapped.append(c);
                }
            }
            String postfix = infixToPostfix(swapped.toString(), rule);
            if (postfix == null) return null;
            String[] tokens = postfix.trim().split("\\s+");
            StringBuilder prefix = new StringBuilder();
            for (int i = tokens.length - 1; i >= 0; i--) {
                prefix.append(tokens[i]).append(' ');
            }
            return prefix.toString().trim();
        }
        return null;
    }

